#!/bin/sh
# Load the Polaris credentials generated by polaris-setup-worker, then start Trino.
set -e
if [ ! -f /out/polaris_creds.env ]; then
  echo "/out/polaris_creds.env not found; the Polaris setup worker must run first."
  exit 1
fi
. /out/polaris_creds.env
export POLARIS_CREDENTIAL="${CLIENT_ID}:${CLIENT_SECRET}"
exec /usr/lib/trino/bin/run-trino
